package com.doms.doms.controller;
import com.doms.doms.dto.DocumentResponseDTO;import com.doms.doms.service.DocumentService;import org.junit.jupiter.api.Test;import org.springframework.core.io.ByteArrayResource;import org.springframework.http.MediaType;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class DocumentControllerTest{
 private static final byte[] PDF="%PDF-1.7\n%%EOF".getBytes(java.nio.charset.StandardCharsets.US_ASCII);
 @Test void authorizedPdfViewUsesInlinePdfHeaders(){DocumentService service=mock(DocumentService.class);DocumentResponseDTO dto=mock(DocumentResponseDTO.class);when(dto.getFileName()).thenReturn("Quarterly report #1.pdf");when(dto.getFileType()).thenReturn("PDF");when(dto.getFileSize()).thenReturn((long)PDF.length);when(service.getDocumentById(7L)).thenReturn(dto);when(service.viewDocument(7L)).thenReturn(new ByteArrayResource(PDF));var response=new DocumentController(service).viewDocument(7L);assertEquals(MediaType.APPLICATION_PDF,response.getHeaders().getContentType());assertTrue(response.getHeaders().getContentDisposition().isInline());assertArrayEquals(PDF,((ByteArrayResource)response.getBody()).getByteArray());}
 @Test void authorizedPdfDownloadUsesAttachmentHeaders(){DocumentService service=mock(DocumentService.class);DocumentResponseDTO dto=mock(DocumentResponseDTO.class);when(dto.getFileName()).thenReturn("Quarterly report #1.PDF");when(dto.getFileType()).thenReturn("PDF");when(dto.getFileSize()).thenReturn((long)PDF.length);when(service.getDocumentById(7L)).thenReturn(dto);when(service.downloadDocument(7L)).thenReturn(new ByteArrayResource(PDF));var response=new DocumentController(service).downloadDocument(7L);assertEquals(MediaType.APPLICATION_PDF,response.getHeaders().getContentType());assertTrue(response.getHeaders().getContentDisposition().isAttachment());assertEquals("Quarterly report #1.PDF",response.getHeaders().getContentDisposition().getFilename());}
}
